<script setup lang="ts">
import { Plus, Search, Pencil, Trash2, FileSpreadsheet } from 'lucide-vue-next'
definePageMeta({layout:'admin',middleware:'admin'})
const me=useState<any>('auth-user'); const search=ref('');const category=ref('');const district=ref('');const status=ref('');const year=ref('')
const {data:cats}=await useFetch('/api/admin/categories'); const {data:dists}=await useFetch('/api/admin/districts')
const {data,refresh}=await useFetch('/api/admin/locations',{query:{search,category,district,status,year}})
async function remove(item:any){if(!confirm(`Hapus lokasi ini?\n\n${item.location_name}\n${item.category} · ${item.district}`))return;await $fetch(`/api/admin/locations/${item.id}`,{method:'DELETE'});await refresh()}
</script>
<template><div class="space-y-6"><UiPageHeader title="Lokasi" description="Kelola seluruh titik GIS dan sumber datanya."><NuxtLink to="/admin/locations/new"><UiButton><Plus class="h-4 w-4"/>Tambah Lokasi</UiButton></NuxtLink></UiPageHeader>
<UiCard class="p-4"><div class="grid gap-3 md:grid-cols-5"><div class="relative"><Search class="absolute left-3 top-3 h-4 w-4 text-slate-400"/><UiInput v-model="search" class="pl-9" placeholder="Cari lokasi..."/></div><UiSelect v-model="category"><option value="">Semua kategori</option><option v-for="c in cats?.categories||[]" :key="c.id" :value="c.id">{{c.name}}</option></UiSelect><UiSelect v-model="district"><option value="">Semua kecamatan</option><option v-for="d in dists?.districts||[]" :key="d.id" :value="d.id">{{d.name}}</option></UiSelect><UiSelect v-model="status"><option value="">Semua status</option><option value="EXISTING">Terpasang</option><option value="PLANNED">Direncanakan</option></UiSelect><UiInput v-model="year" type="number" placeholder="Tahun anggaran"/></div></UiCard>
<UiCard class="overflow-hidden"><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-4 py-3">Lokasi</th><th class="px-4 py-3">Kategori</th><th class="px-4 py-3">Kecamatan</th><th class="px-4 py-3">Status</th><th class="px-4 py-3">TA</th><th class="px-4 py-3">Kondisi</th><th class="px-4 py-3">Sumber</th><th class="px-4 py-3"></th></tr></thead><tbody class="divide-y"><tr v-for="item in data?.locations||[]" :key="item.id" class="hover:bg-slate-50/70"><td class="max-w-sm px-4 py-4 font-medium text-slate-900">{{item.location_name}}</td><td class="px-4 py-4"><span class="inline-flex items-center gap-2"><span class="h-2.5 w-2.5 rounded-full" :style="{background:item.category_color}"></span>{{item.category}}</span></td><td class="px-4 py-4">{{item.district}}</td><td class="px-4 py-4"><UiBadge :variant="item.implementation_status==='PLANNED'?'warning':'success'">{{item.implementation_status==='PLANNED'?'Direncanakan':'Terpasang'}}</UiBadge></td><td class="px-4 py-4">{{item.fiscal_year ?? '—'}}</td><td class="px-4 py-4"><UiBadge :variant="item.condition==='Tidak Baik / Tidak Sesuai'?'destructive':item.condition==='Belum Dinilai'?'warning':'success'">{{item.condition}}</UiBadge></td><td class="px-4 py-4"><div class="flex items-center gap-2"><FileSpreadsheet v-if="item.source_type==='excel'" class="h-4 w-4 text-emerald-600"/><span class="max-w-[180px] truncate" :title="item.source_file_name">{{item.source_type==='excel'?item.source_file_name:'Manual'}}</span></div></td><td class="px-4 py-4"><div class="flex justify-end gap-1"><NuxtLink :to="`/admin/locations/${item.id}`"><UiButton variant="ghost" size="sm"><Pencil class="h-4 w-4"/></UiButton></NuxtLink><UiButton v-if="me?.role==='admin' || me?.role==='manager'" variant="ghost" size="sm" @click="remove(item)"><Trash2 class="h-4 w-4 text-red-600"/></UiButton></div></td></tr></tbody></table></div><EmptyState v-if="!(data?.locations?.length)" title="Belum ada lokasi" description="Tambahkan secara manual atau impor template Excel."/></UiCard></div></template>
